import type { Metadata } from 'next';
import { routeByPath, SITE_URL } from '@/lib/routes';

const ROUTE = '/';
const meta = routeByPath.get(ROUTE)!;

export const metadata: Metadata = {
  title: meta.title,
  description: meta.description,
  alternates: { canonical: SITE_URL + ROUTE },
  openGraph: {
    title: meta.title,
    description: meta.description,
    url: SITE_URL + ROUTE,
    type: 'website',
    images: ["https://pubrica.com/share/pubrica-card.jpg"],
  },
};

const schema = [{"@context":"https://schema.org","@type":"CollectionPage","name":"Research, Writing and Publication Support","url":"https://pubrica.com/","description":"Medical writing, statistics, editing, peer review and publication support for researchers, universities and life-science teams. Since 2009.","inLanguage":"en","isPartOf":{"@type":"WebSite","name":"Pubrica","url":"https://pubrica.com/"},"publisher":{"@type":"Organization","name":"Pubrica","url":"https://pubrica.com/"}},{"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":"What exactly does Pubrica do?","acceptedAnswer":{"@type":"Answer","text":"We provide research, writing, editing, statistical and publication support to authors, institutions, laboratories and publishers, mostly in medicine, life sciences and healthcare. In practice that ranges from running a meta-analysis to editing a thesis to handling a journal submission and the reviewer responses that follow."}},{"@type":"Question","name":"How is your editing different from a language-editing service?","acceptedAnswer":{"@type":"Answer","text":"A language edit corrects grammar and style. Our editors hold doctorates or clinical posts in the field they are editing, so they also question the statistics, verify citations against primary sources, and flag claims the data does not support. Most of what causes a desk rejection sits in that second category."}},{"@type":"Question","name":"What is the turnaround?","acceptedAnswer":{"@type":"Answer","text":"A standard edit takes five to seven business days and a minor edit two to three. Systematic reviews, meta-analyses and regulatory documents are scoped individually. Expedited turnaround is available on most services and is quoted upfront rather than added later."}},{"@type":"Question","name":"Do you keep supporting the paper after submission?","acceptedAnswer":{"@type":"Answer","text":"Yes. Reviewer responses, major and minor revisions, rebuttal letters and resubmission to a second journal are included in the engagement. Support runs until the paper is published or you decide to stop."}},{"@type":"Question","name":"How do you handle unpublished data and confidentiality?","acceptedAnswer":{"@type":"Answer","text":"Every project is covered by a signed confidentiality agreement, access is limited to the assigned team, and material is transferred over encrypted channels. We do not use client material to train anything and we do not pass work to third-party tools."}},{"@type":"Question","name":"Will using your services affect authorship or research integrity?","acceptedAnswer":{"@type":"Answer","text":"No. We work within COPE and ICMJE guidance: we provide professional writing, editing and analysis support, which is acknowledged rather than credited as authorship. Scientific and clinical judgement stays with the named authors, and we will tell you when a request would cross that line."}},{"@type":"Question","name":"Which subjects do you cover?","acceptedAnswer":{"@type":"Answer","text":"All the major clinical and life-science fields, including oncology, cardiology, endocrinology, neurology, psychiatry, radiology, surgery, public health, epidemiology, pharmacology, genomics and health economics. If your field is not listed, ask — the expert register is larger than the page."}}]},{"@context":"https://schema.org","@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://pubrica.com/"},{"@type":"ListItem","position":2,"name":"Research, Writing and Publication Support","item":"https://pubrica.com/"}]}];

